/* Registered water effects: each fall, stream and steam plume has its own local space. */
function createLivingWater(canvas){
 const ctx=canvas.getContext('2d');const skyDay=new Image(),skyNight=new Image();skyDay.src='assets/day.webp';skyNight.src='assets/night.webp';const cloudTiles={};function skyTile(photo,key){if(cloudTiles[key])return cloudTiles[key];const tile=document.createElement('canvas');tile.width=768;tile.height=180;const tc=tile.getContext('2d');tc.drawImage(photo,0,0,photo.naturalWidth*.76,photo.naturalHeight*.18,0,0,768,180);tc.globalCompositeOperation='destination-in';const gx=tc.createLinearGradient(0,0,768,0);gx.addColorStop(0,'transparent');gx.addColorStop(.12,'#fff');gx.addColorStop(.88,'#fff');gx.addColorStop(1,'transparent');tc.fillStyle=gx;tc.fillRect(0,0,768,180);const gy=tc.createLinearGradient(0,0,0,180);gy.addColorStop(0,'#fff');gy.addColorStop(.62,'#fff');gy.addColorStop(1,'transparent');tc.fillStyle=gy;tc.fillRect(0,0,768,180);cloudTiles[key]=tile;return tile;}
 const falls=[
  {points:[[.189,.633],[.199,.630],[.211,.689],[.214,.715],[.202,.716],[.198,.685]],speed:.55},
  {points:[[.348,.706],[.356,.700],[.365,.728],[.371,.755],[.351,.759],[.348,.738]],speed:.72},
  {points:[[.713,.544],[.721,.543],[.713,.568],[.702,.595],[.694,.621],[.687,.620],[.700,.577]],speed:.62},
  {points:[[.937,.642],[.950,.644],[.958,.689],[.964,.734],[.953,.750],[.941,.717]],speed:.84},
  {points:[[.940,.806],[.954,.809],[.960,.872],[.971,.943],[.977,1],[.939,1],[.948,.925],[.943,.862]],speed:1.1},
  {points:[[.830,.943],[.842,.943],[.862,.974],[.868,1],[.844,1]],speed:.9}
 ];
 function clipPoly(points,w,h){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x*w,y*h):ctx.moveTo(x*w,y*h));ctx.closePath();ctx.clip()}
 function fall(f,t,w,h,dark){const xs=f.points.map(p=>p[0]),ys=f.points.map(p=>p[1]),x0=Math.min(...xs)*w,x1=Math.max(...xs)*w,y0=Math.min(...ys)*h,y1=Math.max(...ys)*h;ctx.save();clipPoly(f.points,w,h);const photo=dark?skyNight:skyDay;if(photo.complete&&photo.naturalWidth){const stride=y1-y0,flow=(t*f.speed*.65%1)*stride;ctx.globalAlpha=.26;for(let k=-1;k<2;k++)ctx.drawImage(photo,x0/w*photo.naturalWidth,y0/h*photo.naturalHeight,(x1-x0)/w*photo.naturalWidth,stride/h*photo.naturalHeight,x0,y0+k*stride+flow,x1-x0,stride);ctx.globalAlpha=1;}ctx.globalCompositeOperation='screen';const width=x1-x0;
  for(let j=0;j<15;j++){const xx=x0+((j*.618033)%1)*width;const phase=(t*f.speed+j*.31)%1;const y=y0+phase*(y1-y0);const len=(y1-y0)*(.10+(j%4)*.035);ctx.strokeStyle=dark?'rgba(180,211,239,.22)':'rgba(237,250,255,.48)';ctx.lineWidth=Math.max(.5,w*.00065);ctx.beginPath();ctx.moveTo(xx+Math.sin(t*1.8+j)*width*.08,y);ctx.quadraticCurveTo(xx+width*.1,y+len*.5,xx,y+len);ctx.stroke();}
  for(let j=0;j<8;j++){const phase=(t*f.speed*.7+j*.137)%1;ctx.fillStyle=dark?'rgba(178,211,235,.10)':'rgba(239,253,255,.19)';ctx.beginPath();ctx.ellipse(x0+width*.5+Math.sin(t+j)*width*.23,y1-phase*(y1-y0)*.09,width*(.15+phase*.35),(y1-y0)*.025,0,0,7);ctx.fill();}ctx.restore();
 }
 function steam(t,w,h,dark){ctx.save();const sx=.947*w,sy=.782*h;for(let j=39;j>=0;j--){const age=(t*.22+j/40)%1;const drift=age*w*.097;const x=sx-drift+Math.sin(age*8+t*.38)*age*w*.008;const y=sy-age*h*.105+Math.sin(age*6+j)*age*h*.004;const radius=(.002+age*.013)*w;const alpha=Math.sin(age*Math.PI)*(dark?.30:.42);const g=ctx.createRadialGradient(x,y,0,x,y,radius);g.addColorStop(0,`rgba(${dark?'171,193,214':'245,243,231'},${alpha})`);g.addColorStop(1,`rgba(${dark?'171,193,214':'245,243,231'},0)`);ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(x,y,radius,radius*.7,-.3,0,7);ctx.fill();}ctx.restore();}
 function clouds(t,w,h,dark){ctx.save();clipPoly([[0,0],[.83,0],[.79,.12],[.75,.16],[.62,.15],[.57,.19],[.49,.17],[.40,.20],[.3,.15],[.18,.16],[0,.14]],w,h);for(let layer=0;layer<3;layer++){const speed=[.006,.010,.014][layer],spread=[.13,.10,.065][layer];for(let j=0;j<7;j++){const xx=(((j*.177+t*speed+layer*.13)%1.4)-.2)*w;const yy=(.045+layer*.047+Math.sin(j*3.2)*.026)*h;const radius=spread*w;const g=ctx.createRadialGradient(xx,yy,0,xx,yy,radius);g.addColorStop(0,`rgba(${dark?'131,153,184':'240,247,250'},${[.10,.15,.17][layer]})`);g.addColorStop(1,`rgba(${dark?'131,153,184':'240,247,250'},0)`);ctx.save();ctx.translate(xx,yy);ctx.scale(1,.36);ctx.translate(-xx,-yy);ctx.fillStyle=g;ctx.fillRect(xx-radius,yy-radius,radius*2,radius*2);ctx.restore();}}ctx.restore();}
 function river(t,w,h,dark){const regions=[[[.405,.626],[.552,.628],[.535,.702],[.503,.745],[.490,.801],[.452,.823],[.416,.799],[.401,.765],[.433,.720]],[[.277,.437],[.323,.437],[.335,.46],[.321,.50],[.306,.532],[.288,.529]],[[.626,.437],[.712,.429],[.698,.474],[.660,.501],[.63,.486]],[[.235,.417],[.36,.417],[.359,.438],[.243,.444]]];const photo=dark?skyNight:skyDay;for(const poly of regions){ctx.save();clipPoly(poly,w,h);if(photo.complete&&photo.naturalWidth){ctx.globalAlpha=.22;ctx.drawImage(photo,Math.sin(t*.57)*w*.0009,Math.sin(t*.83)*h*.0015,w,h);ctx.globalAlpha=1;}ctx.globalCompositeOperation='screen';const xs=poly.map(p=>p[0]),ys=poly.map(p=>p[1]),x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);for(let j=0;j<80;j++){const age=(t*.05+j*.618033)%1;const y=(y0+age*(y1-y0))*h;const x=(x0+((j*.414213+t*.005)%1)*(x1-x0))*w;const span=(.001+age*.004)*w;ctx.globalAlpha=(.15+Math.sin(age*Math.PI)*.5)*(dark?.20:.28);ctx.strokeStyle=dark?'#bfd8ef':'#e1f6ff';ctx.lineWidth=.5+age;ctx.beginPath();ctx.moveTo(x-span,y);ctx.quadraticCurveTo(x,y+Math.sin(t+j),x+span,y);ctx.stroke();}ctx.restore();}}

 return {draw(t,s){const d=Math.min(devicePixelRatio||1,1.25);if(canvas.width!==Math.round(s.w*d)||canvas.height!==Math.round(s.h*d)){canvas.width=Math.round(s.w*d);canvas.height=Math.round(s.h*d)}ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,s.w,s.h);ctx.save();const z=1+s.push;ctx.translate(s.w*.5,s.h*.5);ctx.scale(z,z);ctx.translate(-s.focusX*s.w,-s.focusY*s.h);clouds(t,s.w,s.h,s.dark);paintCloudBanks(ctx,t,s.w,s.h,s.dark,false);paintHillFog(ctx,t,s.w,s.h,s.dark,false);for(const f of falls)fall(f,t,s.w,s.h,s.dark);river(t,s.w,s.h,s.dark);steam(t,s.w,s.h,s.dark);ctx.restore();}};
}
